(1, 56, 36, 206, 'N/A', 'Semester I', '2025-05-31 00:00:00', '<h3><strong>BSc (Hons) in Software Engineering &ndash; Individual Project</strong></h3>\r\n\r\n<p><strong>Examination Admission Requisition (EAR) Submission Notice</strong></p>\r\n\r\n<p>You are required to submit the <strong>Examination Admission Requisition (EAR)</strong> form for the <strong>Individual Project</strong> on or before 31st<strong>&nbsp;May&nbsp;2025</strong> via the online submission facility.</p>\r\n\r\n<p><strong>Submit EAR Form Online:</strong><br />\r\n<a href=\"https://www.bms.ac.lk/EAR2018/index.html\" target=\"_new\">https://www.bms.ac.lk/EAR2018/index.html</a></p>\r\n\r\n<p><strong>Project Submission Date:</strong><br />\r\n<strong>4th May 2025</strong></p>\r\n\r\n<p>If you have any questions or need assistance, the <strong>BMS Examination Department Officials</strong> are available during office hours.<br />\r\nEmail: exam@bms.ac.lk</p>\r\n', '682ae50531f03_Attachment2.pdf', '682ae5053212f_Time Table B79 FPT.xlsx', '', '', '2025-05-19 13:48:19', '2025-05-19 00:42:18', '2025-05-19 02:48:19', 68, NULL, 'hasni'),
