ht:none; border-top:none; height:21px; vertical-align:middle; white-space:nowrap\">Please submit the EAR online and follow the below link.</td>\r\n			<td style=\"border-bottom:none; border-left:none; border-right:none; border-top:none; text-align:left; vertical-align:middle; white-space:nowrap\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td colspan=\"5\" style=\"border-bottom:none; border-left:none; border-right:none; border-top:none; height:21px; vertical-align:middle; white-space:nowrap\"><a href=\"https://www.bms.ac.lk/EAR2018/index.html\">https://www.bms.ac.lk/EAR2018/index.html</a></td>\r\n			<td style=\"border-bottom:none; border-left:none; border-right:none; border-top:none; vertical-align:middle; white-space:nowrap\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; border-left:none; border-right:none; border-top:none; height:20px; vertical-align:middle; white-space:nowrap\">&nbsp;</td>\r\n			<td style=\"border-bottom:none; border-left:none; border-right:none; border-top:none; vertical-align:middle; white-space:nowrap\">&nbsp;</td>\r\n			<td style=\"border-bottom:none; border-left:none; border-right:none; border-top:none; vertical-align:middle; white-space:nowrap\">&nbsp;</td>\r\n			<td style=\"border-bottom:none; border-left:none; border-right:none; border-top:none; vertical-align:middle; white-space:nowrap\">&nbsp;</td>\r\n			<td style=\"border-bottom:none; border-left:none; border-right:none; border-top:none; vertical-align:middle; white-space:nowrap\">&nbsp;</td>\r\n			<td style=\"border-bottom:none; border-left:none; border-right:none; border-top:none; vertical-align:middle; white-space:nowrap\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td colspan=\"6\" style=\"border-bottom:none; border-left:none; border-right:none; border-top:none; height:94px; text-align:left; vertical-align:middle; white-space:normal; width:612px\"><strong>Note </strong>- Students are <strong>only</strong> allowed to use the <strong>core text book </strong>and the allowed to make notes on the text book and the case study. You are not allowed to keep any other materials (written post-it notes, printed notes, slides or any other printed material) during the open book examination.</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; border-left:none; border-right:none; border-top:none; height:21px; vertical-align:middle; white-space:nowrap\">&nbsp;</td>\r\n			<td style=\"border-bottom:none; border-left:none; border-right:none; border-top:none; vertical-align:middle; white-space:nowrap\">&nbsp;</td>\r\n			<td style=\"border-bottom:none; border-left:none; border-right:none; border-top:none; vertical-align:middle; white-space:nowrap\">&nbsp;</td>\r\n			<td style=\"border-bottom:none; border-left:none; border-right:none; border-top:none; vertical-align:middle; white-space:nowrap\">&nbsp;</td>\r\n			<td style=\"border-bottom:none; border-left:none; border-right:none; border-top:none; vertical-align:middle; white-space:nowrap\">&nbsp;</td>\r\n			<td style=\"border-bottom:none; border-left:none; border-right:none; border-top:none; vertical-align:middle; white-space:nowrap\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"background-color:#a6a6a6; border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:1px solid black; height:23px; text-align:center; vertical-align:middle; white-space:nowrap\"><strong>Date&nbsp;</strong></td>\r\n			<td style=\"background-color:#a6a6a6; border-bottom:1px solid black; border-left:none; border-right:1px solid black; border-top:1px solid black; text-align:center; vertical-align:middle; white-space:nowrap\"><strong>Day</strong></td>\r\n			<td style=\"background-color:#a6a6a6; border-bottom:1px solid black; border-left:none; border-right:1px solid black; border-top:1px solid black; text-align:center; vertical-align:middle; white-space:nowrap\"><strong>Batch</strong></td>\r\n			<td style=\"background-color:#a6a6a6; border-bottom:1px solid black; border-l