er-left:none; border-right:none; border-top:none; vertical-align:middle; white-space:nowrap\">&nbsp;</td>\r\n			<td style=\"border-bottom:none; border-left:none; border-right:none; border-top:none; vertical-align:middle; white-space:nowrap\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"background-color:#a6a6a6; border-bottom:none; border-left:none; border-right:none; border-top:none; height:23px; text-align:center; vertical-align:middle; white-space:nowrap\"><strong>Date&nbsp;</strong></td>\r\n			<td style=\"background-color:#a6a6a6; border-bottom:none; border-left:none; border-right:none; border-top:none; text-align:center; vertical-align:middle; white-space:nowrap\"><strong>Day</strong></td>\r\n			<td style=\"background-color:#a6a6a6; border-bottom:none; border-left:none; border-right:none; border-top:none; text-align:center; vertical-align:middle; white-space:nowrap\"><strong>Batch</strong></td>\r\n			<td style=\"background-color:#a6a6a6; border-bottom:1px solid black; border-left:none; border-right:none; border-top:1px solid black; text-align:center; vertical-align:middle; white-space:nowrap\"><strong>Mode</strong></td>\r\n			<td style=\"background-color:#a6a6a6; border-bottom:1px solid black; border-left:1px solid black; border-right:none; border-top:1px solid black; text-align:center; vertical-align:middle; white-space:nowrap\"><strong>Subject&nbsp;</strong></td>\r\n			<td style=\"background-color:#a6a6a6; border-bottom:none; border-left:none; border-right:none; border-top:none; text-align:center; vertical-align:middle; white-space:nowrap\"><strong>Time&nbsp;</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; border-left:none; border-right:none; border-top:none; height:74px; text-align:center; vertical-align:middle; white-space:nowrap\">20-Sep-26</td>\r\n			<td style=\"border-bottom:none; border-left:none; border-right:none; border-top:none; text-align:center; vertical-align:middle; white-space:nowrap\">Sun</td>\r\n			<td style=\"bo