(1, '45', 127, 'uploads/induction_banners/banner_6a97b44c773443.88120684.webp', '<p>We are pleased to officially invite you to the Induction for the Science Final Year Degree programme offered by Northumbria University (UK).</p>\r\n', 'Monday, 07th September 2026', '<p>10.00 am &ndash; 2.30pm</p>\r\n\r\n<p>(Kindly be present by 9.00 am to complete registrations).</p>', 'Smart Casual', '<ul>\r\n	<li>Attendance at the Induction Programme is mandatory for all students</li>\r\n	<li>For any queries, feel free to contact Pethmi 070 400 1106/ Dilini 070 400 1086</li>\r\n</ul>', 'admin', '2026-09-01 15:56:15', '2026-09-02 12:06:32'),
(2, '45', 128, 'uploads/induction_banners/banner_6a97aa54514c53.72548072.webp', '<p>We are pleased to invite you to the induction for the Teesside University Masters programme.</p>\r\n', 'Saturday, 07th March 2026', '<p>2.00 PM to 5.00 PM<br />\r\n(Kindly be present by 1.45 PM to complete registrations)</p>', 'Formal Attire', '<ul>\r\n	<li>Attendance at the Induction Programme is&nbsp;<strong>mandatory</strong>&nbsp;for all students.</li>\r\n	<li>For any queries, feel free to contact&nbsp;<strong>Mrxxxxhir xxxxx- 07xxxx 1227.</strong></li>\r\n</ul>', 'admin', '2026-09-02 10:17:16', '2026-09-02 10:17:49');
