INSERT INTO `save_assessment_document_send` (`id`, `programme_id`, `batch_id`, `module_id`, `year_id`, `semester_id`, `assessment_date`, `description`, `attachment_1`, `attachment_2`, `attachment_3`, `attachment_4`, `mail_sent`, `created_at`, `updated_at`, `main_component_id`, `sub_component_id`, `subject_body`, `entered_by`) VALUES
(5, 56, 36, 206, 'N/A', 'Semester I', NULL, '<p>To access the pre-seen information, please follow these instructions:</p>\r\n\r\n<ul>\r\n	<li><a href=\"https://exams.apps.accaglobal.com/examentry/services/examBooking/examPlanner\">Go to Exam Planner</a></li>\r\n	<li>Click on your SBL booked exam details within &lsquo;Your Plan&rsquo;</li>\r\n	<li>Click on the download links for the &lsquo;Pre-seen information&rsquo;&nbsp;</li>\r\n</ul>\r\n\r\n<p>SBL pre-seen information&nbsp;<strong>must</strong>&nbsp;be downloaded from exam planner. Do not access this document from any other source.&nbsp;</p>\r\n', '683187a261abd_Final Year Module Information.pdf', NULL, NULL, NULL, NULL, '2025-05-24 03:16:23', '2025-05-24 03:20:18', 68, NULL, NULL, 'hasni'),
