			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"height:21px; width:88px\">&nbsp;</td>\r\n			<td style=\"height:21px; width:53px\">&nbsp;</td>\r\n			<td style=\"height:21px; width:99px\">&nbsp;</td>\r\n			<td style=\"height:21px; width:333px\">&nbsp;</td>\r\n			<td style=\"border-bottom:none; border-left:none; border-right:none; border-top:none; width:216px\">\r\n			<p>&nbsp;</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td colspan=\"5\" style=\"height:21px; width:789px\">\r\n			<p>Please submit the EAR online and follow the below link.</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td colspan=\"4\" style=\"height:5px; vertical-align:bottom; width:573px\">\r\n			<p><a href=\"https://www.bms.ac.lk/EAR2018/index.html\">https://www.bms.ac.lk/EAR2018/index.html</a></p>\r\n			</td>\r\n			<td style=\"border-bottom:none; border-left:none; border-right:none; border-top:none; width:216px\">\r\n			<p>&nbsp;</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"height:20px; width:88px\">&nbsp;</td>\r\n			<td style=\"height:20px; width:53px\">&nbsp;</td>\r\n			<td style=\"height:20px; width:99px\">&nbsp;</td>\r\n			<td style=\"height:20px; width:333px\">&nbsp;</td>\r\n			<td style=\"border-bottom:none; border-left:none; border-right:none; border-top:none; width:216px\">\r\n			<p>&nbsp;</p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n', '6a3bb8ae441d5_AP I -  exam Time table.pdf', '6a3bb61225880_Exam Guideline.pdf', NULL, NULL, NULL, '2026-06-24 10:48:50', '2026-06-24 10:59:58', 254, NULL, '', 'Prabodha'),
