DELIMITER $$
CREATE TRIGGER `trg_student_after_insert` AFTER INSERT ON `students` FOR EACH ROW BEGIN
    IF NEW.active = 1 
       AND NEW.bms_email IS NOT NULL 
       AND NEW.nic IS NOT NULL THEN

            student_code,
            password,
            bms_email,
            nic,
            is_temp_password,
            created_at
        )
        VALUES (
            NEW.student_code,
            -- Temporary password = DOB YYYYMMDD
            PASSWORD(DATE_FORMAT(NEW.date_of_birth,'%Y%m%d')),
            NEW.bms_email,
            NEW.nic,
            1,
            NOW()
        );
    END IF;
END
$$
