            bms_email = NEW.bms_email,
            nic = NEW.nic
        WHERE student_code = NEW.student_code;

    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_student_deactivate` AFTER UPDATE ON `students` FOR EACH ROW BEGIN
    IF NEW.active = 0 THEN
